import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.BbQrW5_t.js";const u=JSON.parse('{"title":"几何模块","description":"","frontmatter":{"title":"几何模块","date":"2026-09-05T00:00:00.000Z","tags":["初中数学","奥数","几何"]},"headers":[],"relativePath":"study/junior-math/olympiad/geometry/index.md","filePath":"study/junior-math/olympiad/geometry/index.md","lastUpdated":1789887849000}'),o={name:"study/junior-math/olympiad/geometry/index.md"};function i(l,t,h,n,s,m){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="几何模块" tabindex="-1">几何模块 <a class="header-anchor" href="#几何模块" aria-label="Permalink to &quot;几何模块&quot;">​</a></h1><blockquote><p>几何是奥数中最考验&quot;直觉 + 辅助线套路&quot;的模块。所有辅助线技巧都可以归为有限几种模型，本模块的目标就是把模型库装满。</p></blockquote><h2 id="章节目录" tabindex="-1">章节目录 <a class="header-anchor" href="#章节目录" aria-label="Permalink to &quot;章节目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>核心考点</th><th>重要度</th></tr></thead><tbody><tr><td><a href="./01-triangle-congruence.html">第 1 章 三角形与全等进阶</a></td><td>倍长中线、截长补短</td><td>辅助线三大入门套路</td><td>★★★★★</td></tr><tr><td><a href="./02-isosceles-symmetry.html">第 2 章 等腰三角形与轴对称</a></td><td>对称构造、分类讨论</td><td>将军饮马、30° 直角边</td><td>★★★★☆</td></tr><tr><td><a href="./03-area.html">第 3 章 面积问题与等积变形</a></td><td>同底等高、割补法</td><td>燕尾定理、面积比转化</td><td>★★★★☆</td></tr><tr><td><a href="./04-similarity.html">第 4 章 相似三角形进阶</a></td><td>A 字 8 字、一线三等角</td><td>母子相似（射影定理）</td><td>★★★★★</td></tr><tr><td><a href="./05-circle.html">第 5 章 圆与圆幂定理</a></td><td>相交弦、切割线</td><td>四点共圆初步</td><td>★★★★☆</td></tr><tr><td><a href="./06-transformation.html">第 6 章 几何变换</a></td><td>平移、旋转构造</td><td>费马点、60° 旋转</td><td>★★★★☆</td></tr></tbody></table><h2 id="模块学习建议" tabindex="-1">模块学习建议 <a class="header-anchor" href="#模块学习建议" aria-label="Permalink to &quot;模块学习建议&quot;">​</a></h2><ol><li>第 1 章的<strong>倍长中线、截长补短</strong>是辅助线入门第一课，先掌握再谈其他</li><li>第 3 章面积法是被低估的利器——很多线段比问题用面积做比相似快</li><li>第 4 章一线三等角（K 型图）是中考几何压轴的常客，必练</li><li>第 6 章旋转构造难度最高，建议放在全等、相似都熟练后学</li><li>每道例题的辅助线做法都值得记录：<strong>看到什么条件 → 作什么辅助线</strong>，建立条件反射</li></ol>',6)])])}const _=d(o,[["render",i]]);export{u as __pageData,_ as default};
